// Package extdeps maps workspace files read by Bazel module extensions to the
// canonical names of the external repositories those extensions generate.
package extdeps

import (
	"encoding/json"
	"path"
	"regexp"
	"sort"
	"strings"
)

// Mapping describes which external repositories depend on what.
type Mapping struct {
	// FileRepos maps a workspace-relative path to the canonical repository
	// names (as printed by `bazel query --consistent_labels`) generated by the
	// extensions that read it. A name starting with "*" is a suffix pattern
	// (see MatchRepo) used when an extension id could not be resolved to a
	// canonical module name.
	FileRepos map[string][]string
	// ModuleRepos are the canonical repos declared directly in MODULE.bazel
	// (bazel_dep names, as "<name>+").
	ModuleRepos []string
	// LocalPaths are directories of local_path_override / local_repository.
	LocalPaths []string
}

// MatchRepo reports whether canonical repo name matches pattern, which is
// either an exact canonical name or "*<suffix>" for a suffix match.
func MatchRepo(pattern, canonical string) bool {
	if strings.HasPrefix(pattern, "*") {
		return strings.HasSuffix(canonical, pattern[1:])
	}
	return pattern == canonical
}

var extIDRe = regexp.MustCompile(`^(?:@@([^/]*))?//[^%]*%(.+)$`)

// canonicalPrefix derives "<module>+<extension>+" style prefixes (the canonical
// repo name of a repo generated by the extension is prefix + repo name). Ids
// that are not in canonical (@@module+//...) or root (//... / @@//...) form
// yield a "*+<ext>+" suffix-pattern prefix and ok == false.
func canonicalPrefix(id string) (string, bool) {
	m := extIDRe.FindStringSubmatch(id)
	if m == nil {
		if i := strings.LastIndex(id, "%"); i >= 0 {
			return "*+" + id[i+1:] + "+", false
		}
		return "", false
	}
	return m[1] + "+" + m[2] + "+", true
}

var labelRe = regexp.MustCompile(`^@{0,2}//([^:@"]*)(?::(.*))?$`)

// labelPath converts a main-repo label ("//pkg:file", "//:file") to a
// workspace-relative path.
func labelPath(s string) (string, bool) {
	m := labelRe.FindStringSubmatch(s)
	if m == nil {
		return "", false
	}
	pkg, name := m[1], m[2]
	if name == "" && !strings.Contains(s, ":") {
		name = path.Base(pkg)
	}
	if name == "" || name == "." {
		return "", false
	}
	return path.Join(pkg, name), true
}

type lockfile struct {
	ModuleExtensions map[string]map[string]struct {
		RecordedInputs     []string                   `json:"recordedInputs"`
		GeneratedRepoSpecs map[string]json.RawMessage `json:"generatedRepoSpecs"`
	} `json:"moduleExtensions"`
}

// FromLockfile builds the file→repos mapping from a MODULE.bazel.lock.
func FromLockfile(data []byte) (Mapping, error) {
	var l lockfile
	if err := json.Unmarshal(data, &l); err != nil {
		return Mapping{}, err
	}
	m := Mapping{FileRepos: map[string][]string{}}
	for id, variants := range l.ModuleExtensions {
		prefix, _ := canonicalPrefix(id)
		for _, v := range variants {
			var files []string
			for _, in := range v.RecordedInputs {
				rest, ok := strings.CutPrefix(in, "FILE:@@//")
				if !ok {
					continue
				}
				if i := strings.LastIndex(rest, " "); i >= 0 {
					rest = rest[:i]
				}
				// Recorded FILE inputs are workspace-relative paths, not labels.
				if p := path.Clean(rest); p != "." && !strings.HasPrefix(p, "..") {
					files = append(files, p)
				}
			}
			for _, f := range files {
				for name := range v.GeneratedRepoSpecs {
					m.FileRepos[f] = append(m.FileRepos[f], prefix+name)
				}
			}
		}
	}
	for f := range m.FileRepos {
		m.FileRepos[f] = uniqSorted(m.FileRepos[f])
	}
	return m, nil
}

// Merge returns the union of m and o.
func (m Mapping) Merge(o Mapping) Mapping {
	r := Mapping{FileRepos: map[string][]string{}}
	for _, src := range []map[string][]string{m.FileRepos, o.FileRepos} {
		for f, repos := range src {
			r.FileRepos[f] = append(r.FileRepos[f], repos...)
		}
	}
	for f := range r.FileRepos {
		r.FileRepos[f] = uniqSorted(r.FileRepos[f])
	}
	r.ModuleRepos = uniqSorted(append(append([]string(nil), m.ModuleRepos...), o.ModuleRepos...))
	r.LocalPaths = uniqSorted(append(append([]string(nil), m.LocalPaths...), o.LocalPaths...))
	return r
}

func uniqSorted(in []string) []string {
	if len(in) == 0 {
		return nil
	}
	s := append([]string(nil), in...)
	sort.Strings(s)
	out := s[:1]
	for _, x := range s[1:] {
		if x != out[len(out)-1] {
			out = append(out, x)
		}
	}
	return out
}
